function getCrowdstrikeTranslation(key, lang) {
    return (crowdstrikeTranslations[lang] && crowdstrikeTranslations[lang][key]) ||
           (crowdstrikeTranslations.en && crowdstrikeTranslations.en[key]) || null;
}

function applyCrowdstrikeTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.crowdstrike.") || key.startsWith("review.common."))) {
            const translation = getCrowdstrikeTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    
}

window.addEventListener("languageChanged", e => setTimeout(() => applyCrowdstrikeTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyCrowdstrikeTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyCrowdstrikeTranslations(window.i18n?.getCurrentLanguage() || "en");
}
